  const resources = [["Bombas", "4 / 5", "1 gap"], ["Geradores", "2 / 3", "G-02 standby"], ["Drones", "3 / 4", "1 em voo"], ["Veículos", "8 / 9", "V-11"], ["Rádios", "19 / 20", "1 charging"]];
